export type JobStatus = (typeof JobStatus)[keyof typeof JobStatus];

export const JobStatus = {
  pending: "pending",
  running: "running",
  succeeded: "succeeded",
  failed: "failed",
} as const;

export type JobResult = { [key: string]: unknown } | null;

export interface Job {
  id: string;
  orgId?: string | null;
  kind: string;
  status: JobStatus;
  attempts: number;
  /** Total automatic-attempt budget (initial run + auto-retries).
When `attempts` reaches this value the worker stops retrying
and marks the job `failed`.
 */
  maxAttempts: number;
  progress?: number;
  result?: JobResult;
  error?: string | null;
  /** True once an operator has requested cancellation. For `running`
jobs the worker will rewrite the terminal state to `failed`
with error "Cancelled by operator" once the handler returns.
 */
  cancelRequested?: boolean;
  enqueuedAt: string;
  startedAt?: string | null;
  completedAt?: string | null;
  /** Earliest time the worker is allowed to claim this job again.
Set to a future timestamp while a job is in retry-backoff
after a transient failure; `null` means the job is ready to
run immediately (the common case).
 */
  scheduledFor?: string | null;
}

export type JobKindSettingKind =
  (typeof JobKindSettingKind)[keyof typeof JobKindSettingKind];

export const JobKindSettingKind = {
  ingest_csv: "ingest_csv",
  ingest_mock_erp: "ingest_mock_erp",
  run_analysis_cycle: "run_analysis_cycle",
  run_collector: "run_collector",
} as const;

export interface JobKindSetting {
  kind: JobKindSettingKind;
  /**
   * Effective auto-retry budget for this kind: operator override if
one is set, otherwise the in-code default.

   * @minimum 1
   */
  maxAttempts: number;
  /**
   * The in-code default for this kind. Shown in the UI so operators
can see what value the system would fall back to if the
override were removed.

   * @minimum 1
   */
  defaultMaxAttempts: number;
  /** True when `maxAttempts` comes from the `job_kind_settings`
table; false when it falls back to `defaultMaxAttempts`.
 */
  isOverride: boolean;
  /** When the override was last written. Null when there is no override. */
  updatedAt?: string | null;
}

export interface UpdateJobKindSettingRequest {
  /**
   * @minimum 1
   * @maximum 100
   */
  maxAttempts: number;
}

/**
 * `failed` when the job was `pending` and was transitioned
immediately, `running` when the cancel flag was set on a
running job (the worker will mark it failed when the
handler returns).

 */
export type JobCancelledStatus =
  (typeof JobCancelledStatus)[keyof typeof JobCancelledStatus];

export const JobCancelledStatus = {
  running: "running",
  failed: "failed",
} as const;

export interface JobCancelled {
  jobId: string;
  /** `failed` when the job was `pending` and was transitioned
immediately, `running` when the cancel flag was set on a
running job (the worker will mark it failed when the
handler returns).
 */
  status: JobCancelledStatus;
  /** Always true on a successful response. */
  cancelRequested: boolean;
  /** True if the job was pending and is now marked failed; false
if the job was running and the cancel flag was set.
 */
  cancelledImmediately: boolean;
}

